import { useNavigate } from 'react-router-dom';
import { motion } from 'framer-motion';
import { Sparkles, Gift, Bot, Heart } from 'lucide-react';
import { useUserStore } from '@/stores/userStore';

const features = [
  { icon: Sparkles, emoji: '✨', label: '性格测评', path: '/assessment', color: 'from-star-gold/20 to-aurora-cyan/20', border: 'hover:border-star-gold/50' },
  { icon: Gift, emoji: '🎁', label: '本周盲盒', path: '/blindbox', color: 'from-soft-pink/20 to-star-gold/20', border: 'hover:border-soft-pink/50' },
  { icon: Bot, emoji: '🤖', label: 'AI 助手', path: '/chat', color: 'from-aurora-cyan/20 to-star-purple/20', border: 'hover:border-aurora-cyan/50' },
  { icon: Heart, emoji: '💚', label: '帮扶专区', path: '/support', color: 'from-soft-pink/20 to-aurora-cyan/20', border: 'hover:border-soft-pink/50' },
];

const stats = [
  { value: '80%', label: '减少无效社交' },
  { value: '3倍', label: '契合度提升' },
  { value: 'AI', label: '全程陪伴' },
];

const containerVariants = {
  hidden: { opacity: 0 },
  visible: {
    opacity: 1,
    transition: { staggerChildren: 0.12, delayChildren: 0.2 },
  },
};

const itemVariants = {
  hidden: { opacity: 0, y: 30 },
  visible: { opacity: 1, y: 0, transition: { duration: 0.5, ease: 'easeOut' } },
};

export default function Home() {
  const navigate = useNavigate();
  const isAuthenticated = useUserStore((s) => s.isAuthenticated);

  const handleNavigate = (path: string) => {
    if (!isAuthenticated && (path === '/assessment' || path === '/blindbox')) {
      navigate('/login');
    } else {
      navigate(path);
    }
  };

  const ctaTarget = (path: string) => (isAuthenticated ? path : '/login');

  return (
    <motion.div
      variants={containerVariants}
      initial="hidden"
      animate="visible"
      className="space-y-10 pb-4"
    >
      {/* Hero 区域 */}
      <section className="text-center space-y-5 pt-4">
        <motion.h1
          variants={itemVariants}
          className="font-display text-4xl leading-tight text-gradient-main"
        >
          每周一遇，<br />遇见懂你的人
        </motion.h1>
        <motion.p
          variants={itemVariants}
          className="text-moon-white/60 text-lg font-body"
        >
          AI 共情治愈 · 同城兴趣结伴
        </motion.p>
        <motion.div variants={itemVariants} className="flex items-center justify-center gap-4">
          <button
            onClick={() => navigate(ctaTarget('/assessment'))}
            className="btn-primary px-8 py-3 text-base"
          >
            开始测评
          </button>
          <button
            onClick={() => navigate(ctaTarget('/blindbox'))}
            className="btn-secondary px-8 py-3 text-base"
          >
            探索盲盒
          </button>
        </motion.div>
      </section>

      {/* 核心功能入口 */}
      <section className="grid grid-cols-2 gap-4">
        {features.map((feat, i) => (
          <motion.button
            key={feat.path}
            variants={itemVariants}
            onClick={() => handleNavigate(feat.path)}
            className={`glass rounded-2xl p-5 text-center space-y-3 transition-all duration-300
              hover:-translate-y-1 hover:shadow-glow-gold ${feat.border}`}
          >
            <div className={`inline-flex items-center justify-center w-12 h-12 rounded-xl
              bg-gradient-to-br ${feat.color}`}>
              <span className="text-2xl">{feat.emoji}</span>
            </div>
            <p className="text-moon-white font-medium text-sm">{feat.label}</p>
          </motion.button>
        ))}
      </section>

      {/* 平台价值主张 */}
      <section className="space-y-3">
        <h2 className="text-center text-moon-white/50 text-sm font-medium tracking-wider">
          为什么选择星遇
        </h2>
        <div className="grid grid-cols-3 gap-3">
          {stats.map((stat, i) => (
            <motion.div
              key={stat.label}
              variants={itemVariants}
              className="glass-light rounded-xl p-4 text-center space-y-1"
            >
              <p className="text-xl font-bold text-gradient-main">{stat.value}</p>
              <p className="text-[11px] text-moon-white/50">{stat.label}</p>
            </motion.div>
          ))}
        </div>
      </section>
    </motion.div>
  );
}
