import { create } from 'zustand';
import { persist } from 'zustand/middleware';

export type MessageType = 'text' | 'ai-suggestion' | 'emotion-care' | 'activity-card';

export interface Message {
  id: string;
  senderId: string;
  content: string;
  type: MessageType;
  timestamp: number;
}

interface ChatStore {
  messages: Message[];
  aiSuggestions: string[];
  showContinuation: boolean;
  addMessage: (msg: Omit<Message, 'id' | 'timestamp'>) => void;
  sendAiSuggestion: (index: number) => void;
  setAiSuggestions: (suggestions: string[]) => void;
  setShowContinuation: (show: boolean) => void;
  generateAiSuggestions: (userPersonality: string, matchNickname: string) => void;
}

const negativeEmotionWords = ['难过', '伤心', '焦虑', '压力', '累', '烦', '孤独', '崩溃', '沮丧', '失落', '无助', 'emo'];

const emotionCareResponses = [
  '我感受到了你的情绪，给自己一些温柔的时间吧 🌙',
  '每个人都会有低落的时候，这很正常，你并不孤单 💫',
  '深呼吸，慢慢来，我在这里陪着你 🌟',
];

const continuationSuggestions = [
  '聊聊你最近看过的一本书或一部电影？',
  '分享一下你最想去旅行的地方？',
  '你平时周末喜欢怎么度过？',
];

export const useChatStore = create<ChatStore>()(
  persist(
    (set, get) => ({
      messages: [],
      aiSuggestions: [],
      showContinuation: false,
      addMessage: (msg) => {
        const newMsg: Message = {
          ...msg,
          id: crypto.randomUUID(),
          timestamp: Date.now(),
        };
        const messages = [...get().messages, newMsg];

        // 检测消极情绪
        if (msg.senderId === 'user' && msg.type === 'text') {
          const hasNegative = negativeEmotionWords.some((w) => msg.content.includes(w));
          if (hasNegative) {
            const careMsg: Message = {
              id: crypto.randomUUID(),
              senderId: 'ai',
              content: emotionCareResponses[Math.floor(Math.random() * emotionCareResponses.length)],
              type: 'emotion-care',
              timestamp: Date.now() + 1,
            };
            messages.push(careMsg);
          }
        }

        set({ messages });

        // 检查是否需要续聊建议
        if (messages.length > 0 && messages.length % 6 === 0) {
          set({ showContinuation: true });
        }
      },
      sendAiSuggestion: (index) => {
        const { aiSuggestions } = get();
        if (aiSuggestions[index]) {
          get().addMessage({
            senderId: 'user',
            content: aiSuggestions[index],
            type: 'text',
          });
        }
      },
      setAiSuggestions: (suggestions) => set({ aiSuggestions: suggestions }),
      setShowContinuation: (show) => set({ showContinuation: show }),
      generateAiSuggestions: (_userPersonality, matchNickname) => {
        const suggestions = [
          `嗨 ${matchNickname}，你平时喜欢怎样放松自己？`,
          `${matchNickname}，最近有什么让你开心的小事吗？`,
          `对了 ${matchNickname}，你有没有什么特别想尝试的新活动？`,
        ];
        set({ aiSuggestions: suggestions });
      },
    }),
    {
      name: 'star-blindbox-chat',
      partialize: (state) => ({ messages: state.messages }),
    }
  )
);

export { continuationSuggestions };
