import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { useAssessmentStore } from '@/stores/assessmentStore';

const questions = [
  // 开放性 Openness (O) - 3题
  { dimension: 'O', text: '面对全新的体验和想法，你通常：', low: '倾向于按熟悉方式做事', high: '极其渴望尝试' },
  { dimension: 'O', text: '对于艺术、音乐和文学，你：', low: '基本无感', high: '深深着迷' },
  { dimension: 'O', text: '当遇到与自己不同的观点时，你：', low: '坚持己见', high: '好奇倾听' },
  // 尽责性 Conscientiousness (C) - 3题
  { dimension: 'C', text: '在工作和生活中，你：', low: '随性而为', high: '严格规划' },
  { dimension: 'C', text: '面对待办事项，你通常：', low: '能拖则拖', high: '立即行动' },
  { dimension: 'C', text: '关于目标和承诺，你：', low: '灵活变通', high: '坚定不移' },
  // 外向性 Extraversion (E) - 3题
  { dimension: 'E', text: '在社交场合中，你：', low: '安静观察', high: '活跃中心' },
  { dimension: 'E', text: '你的能量恢复方式是：', low: '独处充电', high: '社交充电' },
  { dimension: 'E', text: '面对陌生人，你：', low: '谨慎慢热', high: '热情自来' },
  // 宜人性 Agreeableness (A) - 3题
  { dimension: 'A', text: '当他人需要帮助时，你：', low: '量力而行', high: '毫不犹豫' },
  { dimension: 'A', text: '在意见分歧时，你：', low: '坚持己见', high: '寻求共识' },
  { dimension: 'A', text: '你对他人情感的感知：', low: '较为迟钝', high: '极其敏锐' },
  // 神经质 Neuroticism (N) - 3题
  { dimension: 'N', text: '面对压力和挫折，你：', low: '从容应对', high: '容易焦虑' },
  { dimension: 'N', text: '你的情绪波动频率：', low: '稳定如水', high: '起伏较大' },
  { dimension: 'N', text: '对不确定的事情，你：', low: '坦然接受', high: '惴惴不安' },
];

export default function Assessment() {
  const navigate = useNavigate();
  const { answers, setAnswer, calculateResult } = useAssessmentStore();
  const [currentIndex, setCurrentIndex] = useState(0);

  const currentQuestion = questions[currentIndex];
  const currentValue = answers[currentIndex] || 5;
  const isLast = currentIndex === questions.length - 1;

  const handlePrev = () => {
    if (currentIndex > 0) setCurrentIndex(currentIndex - 1);
  };

  const handleNext = () => {
    if (isLast) {
      calculateResult();
      navigate('/assessment/result');
    } else {
      setCurrentIndex(currentIndex + 1);
    }
  };

  const slideVariants = {
    enter: (direction: number) => ({
      x: direction > 0 ? 200 : -200,
      opacity: 0,
    }),
    center: {
      x: 0,
      opacity: 1,
    },
    exit: (direction: number) => ({
      x: direction > 0 ? -200 : 200,
      opacity: 0,
    }),
  };

  const [direction, setDirection] = useState(0);

  const goNext = () => {
    setDirection(1);
    handleNext();
  };

  const goPrev = () => {
    setDirection(-1);
    handlePrev();
  };

  return (
    <div className="flex flex-col items-center min-h-[80vh] py-8 px-4">
      {/* 题号指示器 */}
      <div className="flex gap-1.5 mb-8 flex-wrap justify-center max-w-xs">
        {questions.map((_, i) => (
          <div
            key={i}
            className={`w-2.5 h-2.5 rounded-full transition-all duration-300 ${
              i === currentIndex
                ? 'bg-star-gold animate-pulse-glow scale-125'
                : i < currentIndex || answers[i]
                  ? 'bg-aurora-cyan'
                  : 'bg-dark-matter'
            }`}
          />
        ))}
      </div>

      {/* 题目内容区域 */}
      <div className="flex-1 flex flex-col items-center justify-center w-full max-w-md relative overflow-hidden">
        <AnimatePresence mode="wait" custom={direction}>
          <motion.div
            key={currentIndex}
            custom={direction}
            variants={slideVariants}
            initial="enter"
            animate="center"
            exit="exit"
            transition={{ duration: 0.3, ease: 'easeInOut' }}
            className="flex flex-col items-center w-full"
          >
            {/* 维度标签 */}
            <span className="text-xs font-body text-aurora-cyan/60 mb-2 uppercase tracking-wider">
              {currentQuestion.dimension}
            </span>

            {/* 题目文字 */}
            <h2 className="text-lg font-medium text-moon-white text-center mb-8 font-body leading-relaxed">
              {currentQuestion.text}
            </h2>

            {/* 滑块区域 */}
            <div className="w-full px-2">
              {/* 两端标签 */}
              <div className="flex justify-between mb-3">
                <span className="text-xs text-moon-white/40 font-body max-w-[120px] text-left">
                  {currentQuestion.low}
                </span>
                <span className="text-xs text-moon-white/40 font-body max-w-[120px] text-right">
                  {currentQuestion.high}
                </span>
              </div>

              {/* 滑动选择器 */}
              <input
                type="range"
                min={1}
                max={10}
                value={currentValue}
                onChange={(e) => setAnswer(currentIndex, Number(e.target.value))}
                className="assessment-slider w-full h-2 rounded-full appearance-none cursor-pointer bg-dark-matter"
                style={{
                  background: `linear-gradient(to right, #38F9D7 0%, #38F9D7 ${(currentValue - 1) * 100 / 9}%, #2D2B55 ${(currentValue - 1) * 100 / 9}%, #2D2B55 100%)`,
                }}
              />

              {/* 滑动值显示 */}
              <div className="text-center mt-3">
                <span className="text-2xl font-display text-star-gold">{currentValue}</span>
                <span className="text-xs text-moon-white/30 font-body ml-1">/ 10</span>
              </div>

              {/* 刻度 */}
              <div className="flex justify-between mt-1 px-0.5">
                {Array.from({ length: 10 }, (_, i) => (
                  <span
                    key={i}
                    className={`text-[10px] font-body ${
                      i + 1 === currentValue ? 'text-star-gold' : 'text-moon-white/20'
                    }`}
                  >
                    {i + 1}
                  </span>
                ))}
              </div>
            </div>
          </motion.div>
        </AnimatePresence>
      </div>

      {/* 导航按钮 */}
      <div className="flex gap-4 mt-8 items-center">
        {currentIndex > 0 && (
          <button
            onClick={goPrev}
            className="btn-secondary px-6 py-2.5 text-sm font-body"
          >
            上一题
          </button>
        )}
        <button
          onClick={goNext}
          className="btn-primary px-8 py-2.5 text-sm font-body"
        >
          {isLast ? '查看结果' : '下一题'}
        </button>
      </div>

      {/* 进度提示 */}
      <p className="text-moon-white/30 text-xs font-body mt-4">
        {currentIndex + 1} / {questions.length}
      </p>
    </div>
  );
}
