import { useState } from 'react';
import { motion } from 'framer-motion';
import { Send } from 'lucide-react';

const practiceSteps = [
  { title: '打招呼', example: '你好，我是xxx，很高兴认识你', tip: '从简单问候开始，不需要想太多' },
  { title: '找话题', example: '你喜欢什么类型的电影？', tip: '从兴趣爱好出发，找到共同话题' },
  { title: '深入交流', example: '我最近看了一部很感人的电影，让我想到...', tip: '分享感受，让对方了解真实的你' },
  { title: '约定下次', example: '下次有新片上映，要不要一起去看？', tip: '自然地延伸到线下，低压力邀约' },
];

const organizations = [
  { name: '心晴热线', desc: '24小时心理援助热线，专业倾听，温暖陪伴', contact: '400-161-9995', tag: '热线' },
  { name: '北京心理援助中心', desc: '提供免费心理评估与咨询服务', contact: '010-82951332', tag: '咨询' },
  { name: '暖光互助小组', desc: '社恐青年互助社群，定期线下温暖聚会', contact: '微信公众号: 暖光互助', tag: '社群' },
  { name: '青年心灵驿站', desc: '面向18-35岁青年的免费心理支持', contact: 'app搜索: 心灵驿站', tag: 'APP' },
  { name: '同行者计划', desc: '一对一心理陪伴，专业志愿者匹配', contact: 'tongxingzhe@example.com', tag: '陪伴' },
];

const initialPosts = [
  { id: '1', content: '今天加班到很晚，有点累但还好', warmCount: 5, warmed: false, avatar: '🌙' },
  { id: '2', content: '周末一个人去看了展，意外地很治愈', warmCount: 12, warmed: false, avatar: '🎨' },
  { id: '3', content: '社恐人表示在这里感觉很安全', warmCount: 23, warmed: false, avatar: '💜' },
];

const avatarEmojis = ['🌙', '🎨', '💜', '🌟', '✨', '🌊', '🍃', '🌸'];

const tabLabels = ['社交练习', 'AI 聊天', '心理社团', '情绪树洞'];

function getAiReply(content: string): string {
  if (/你好|嗨|hi|嘿/i.test(content)) {
    return '你好呀！很高兴见到你，今天感觉怎么样？ 😊';
  }
  if (/紧张|害怕|不敢|社恐/.test(content)) {
    return '紧张是很正常的感受，慢慢来，不需要强迫自己。我在这里陪着你 💜';
  }
  if (/喜欢|爱好|爱/.test(content)) {
    return '听起来很有趣呢！能多告诉我一些吗？';
  }
  if (/工作|上班|加班/.test(content)) {
    return '工作确实会让人有压力，记得给自己放松的时间哦';
  }
  if (/谢谢|感谢/.test(content)) {
    return '不用谢！你愿意开口说话就已经很棒了 🌟';
  }
  const defaults = ['嗯嗯，我在听，继续说 🌙', '我理解你的感受，这很正常', '你做得很好，给自己一些鼓励吧 ✨'];
  return defaults[Math.floor(Math.random() * defaults.length)];
}

export default function Support() {
  const [activeTab, setActiveTab] = useState(0);
  const [step, setStep] = useState(0);

  // AI chat state
  const [chatMessages, setChatMessages] = useState<Array<{ id: string; sender: 'user' | 'ai'; content: string }>>([
    { id: 'welcome', sender: 'ai', content: '你好呀！我是星遇 AI 伙伴，可以和我练习聊天哦 😊' },
  ]);
  const [chatInput, setChatInput] = useState('');

  // Tree hole state
  const [posts, setPosts] = useState(initialPosts);
  const [postInput, setPostInput] = useState('');

  const handleSendMessage = () => {
    if (!chatInput.trim()) return;
    const userMsg = { id: crypto.randomUUID(), sender: 'user' as const, content: chatInput.trim() };
    const aiReply = getAiReply(chatInput.trim());
    const aiMsg = { id: crypto.randomUUID(), sender: 'ai' as const, content: aiReply };
    setChatMessages((prev) => [...prev, userMsg, aiMsg]);
    setChatInput('');
  };

  const handlePostPublish = () => {
    if (!postInput.trim() || postInput.length > 50) return;
    const newPost = {
      id: crypto.randomUUID(),
      content: postInput.trim(),
      warmCount: 0,
      warmed: false,
      avatar: avatarEmojis[Math.floor(Math.random() * avatarEmojis.length)],
    };
    setPosts((prev) => [newPost, ...prev]);
    setPostInput('');
  };

  const toggleWarm = (id: string) => {
    setPosts((prev) =>
      prev.map((p) =>
        p.id === id
          ? { ...p, warmed: !p.warmed, warmCount: p.warmed ? p.warmCount - 1 : p.warmCount + 1 }
          : p
      )
    );
  };

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      className="px-4 pb-8 space-y-5"
    >
      {/* 专区首页 */}
      <div className="text-center pt-6 pb-2 space-y-2">
        <h1 className="text-gradient-warm font-display text-3xl">你并不孤单</h1>
        <p className="text-moon-white/50 text-sm">星遇帮扶专区</p>
      </div>

      {/* Tab 切换 */}
      <div className="flex justify-center gap-6 border-b border-moon-white/10">
        {tabLabels.map((label, i) => (
          <button
            key={i}
            onClick={() => setActiveTab(i)}
            className={`pb-2 text-sm transition-colors ${
              activeTab === i
                ? 'text-aurora-cyan border-b-2 border-aurora-cyan'
                : 'text-moon-white/40'
            }`}
          >
            {label}
          </button>
        ))}
      </div>

      {/* 模块1：分步社交练习 */}
      {activeTab === 0 && (
        <motion.div
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          className="space-y-5"
        >
          {/* 步骤指示器 */}
          <div className="flex justify-center gap-3">
            {practiceSteps.map((_, i) => (
              <div
                key={i}
                className={`w-3 h-3 rounded-full transition-colors ${
                  i === step
                    ? 'bg-aurora-cyan'
                    : i < step
                    ? 'bg-aurora-cyan/50'
                    : 'bg-dark-matter'
                }`}
              />
            ))}
          </div>

          {/* 当前步骤内容 */}
          <div className="space-y-3 text-center">
            <p className="text-moon-white/50 text-sm">步骤 {step + 1} / 4</p>
            <h2 className="font-display text-xl text-star-gold">{practiceSteps[step].title}</h2>

            <div className="glass-light rounded-xl p-4 mx-auto max-w-sm">
              <p className="text-moon-white/70 text-sm mb-1">💬 示例话术</p>
              <p className="text-moon-white text-sm">"{practiceSteps[step].example}"</p>
            </div>

            <p className="text-aurora-cyan/70 text-sm">💡 {practiceSteps[step].tip}</p>

            <button
              onClick={() => {
                if (step < 3) setStep(step + 1);
                else setStep(0);
              }}
              style={{
                background: 'linear-gradient(135deg, rgba(245,200,66,0.55), rgba(56,249,215,0.55))',
                fontWeight: 400,
                letterSpacing: '0.15em',
              }}
              className="mt-4 text-sm rounded-full px-6 py-2.5 border border-white/40 text-deep-space inline-flex items-center justify-center gap-2 transition-all hover:shadow-glow-gold"
            >
              {step < 3 ? (
                <span>下一步</span>
              ) : (
                <>
                  <span>完成练习</span>
                  <span className="text-xs">🎉</span>
                </>
              )}
            </button>
          </div>
        </motion.div>
      )}

      {/* 模块2：AI 模拟聊天 */}
      {activeTab === 1 && (
        <motion.div
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          className="space-y-3 flex flex-col"
        >
          <div className="flex-1 space-y-3 max-h-[50vh] overflow-y-auto pr-1">
            {chatMessages.map((msg) => (
              <div
                key={msg.id}
                className={`flex ${msg.sender === 'user' ? 'justify-end' : 'justify-start'}`}
              >
                <div
                  className={`max-w-[75%] px-4 py-2.5 text-sm ${
                    msg.sender === 'ai'
                      ? 'bg-gradient-to-r from-soft-pink/10 to-star-gold/10 rounded-2xl rounded-bl-md'
                      : 'bg-aurora-cyan/20 rounded-2xl rounded-br-md'
                  }`}
                >
                  <p className="text-moon-white">{msg.content}</p>
                </div>
              </div>
            ))}
          </div>

          <div className="flex gap-2 sticky bottom-0">
            <input
              type="text"
              value={chatInput}
              onChange={(e) => setChatInput(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSendMessage()}
              placeholder="输入你想说的话..."
              className="flex-1 glass-light rounded-xl px-4 py-2.5 text-sm text-moon-white placeholder:text-moon-white/30 outline-none"
            />
            <button
              onClick={handleSendMessage}
              className="btn-primary flex items-center gap-1"
            >
              <Send size={16} />
            </button>
          </div>
        </motion.div>
      )}

      {/* 模块3：心理公益社团 */}
      {activeTab === 2 && (
        <motion.div
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          className="space-y-3"
        >
          {organizations.map((org, i) => (
            <div
              key={i}
              className="bg-gradient-to-r from-soft-pink/10 to-star-gold/5 rounded-xl p-4 space-y-2"
            >
              <div className="flex items-center gap-2">
                <span className="font-medium text-moon-white">{org.name}</span>
                <span className="bg-soft-pink/20 text-soft-pink text-[10px] px-2 py-0.5 rounded-full">
                  {org.tag}
                </span>
              </div>
              <p className="text-moon-white/60 text-sm">{org.desc}</p>
              <p className="text-aurora-cyan/80 text-xs">📞 {org.contact}</p>
            </div>
          ))}
        </motion.div>
      )}

      {/* 模块4：匿名情绪树洞 */}
      {activeTab === 3 && (
        <motion.div
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          className="space-y-4"
        >
          {/* 发布区 */}
          <div className="flex gap-2">
            <input
              type="text"
              value={postInput}
              onChange={(e) => setPostInput(e.target.value)}
              placeholder="说说你的心情...（50字以内）"
              maxLength={50}
              className="flex-1 glass-light rounded-xl px-4 py-2.5 text-sm text-moon-white placeholder:text-moon-white/30 outline-none"
            />
            <button
              onClick={handlePostPublish}
              disabled={!postInput.trim() || postInput.length > 50}
              className="btn-primary disabled:opacity-40"
            >
              发布
            </button>
          </div>

          {/* 帖子列表 */}
          <div className="space-y-3">
            {posts.map((post) => (
              <div
                key={post.id}
                className="bg-gradient-to-r from-soft-pink/5 to-star-gold/5 rounded-xl p-3 space-y-2"
              >
                <div className="flex items-start gap-2">
                  <span className="text-lg">{post.avatar}</span>
                  <p className="text-moon-white text-sm flex-1">{post.content}</p>
                </div>
                <button
                  onClick={() => toggleWarm(post.id)}
                  className={`text-xs transition-colors ${
                    post.warmed ? 'text-soft-pink' : 'text-moon-white/40'
                  }`}
                >
                  ❤️ {post.warmCount}
                </button>
              </div>
            ))}
          </div>
        </motion.div>
      )}
    </motion.div>
  );
}
