import { useState, useRef, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion } from 'framer-motion';
import { ArrowLeft, Send, X, Sparkles } from 'lucide-react';
import { useChatStore, continuationSuggestions } from '@/stores/chatStore';
import { useMatchStore } from '@/stores/matchStore';
import { useAssessmentStore } from '@/stores/assessmentStore';

const autoReplies = [
  '哈哈，我也这么觉得！',
  '这个想法很有趣呢',
  '我最近也在关注这个',
  '下次我们可以一起去体验',
  '说得太对了',
  '你平时还喜欢做什么？',
  '这个推荐不错，记下了！',
];

export default function Chat() {
  const navigate = useNavigate();
  const { currentMatch } = useMatchStore();
  const { result } = useAssessmentStore();
  const {
    messages,
    aiSuggestions,
    showContinuation,
    addMessage,
    sendAiSuggestion,
    generateAiSuggestions,
    setShowContinuation,
  } = useChatStore();

  const [inputText, setInputText] = useState('');
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  // 进入聊天页时，生成 AI 破冰建议
  useEffect(() => {
    if (currentMatch && aiSuggestions.length === 0) {
      generateAiSuggestions(
        result?.personalityType || '探索者',
        currentMatch.nickname
      );
    }
  }, [currentMatch, aiSuggestions.length, generateAiSuggestions, result?.personalityType]);

  // 自动滚动到底部
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, showContinuation]);

  const handleSend = () => {
    const text = inputText.trim();
    if (!text) return;
    addMessage({ senderId: 'user', content: text, type: 'text' });
    setInputText('');

    // 模拟对方回复
    const delay = 1000 + Math.random() * 2000;
    setTimeout(() => {
      const reply = autoReplies[Math.floor(Math.random() * autoReplies.length)];
      addMessage({
        senderId: currentMatch?.id || 'match',
        content: reply,
        type: 'text',
      });
    }, delay);
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const handleContinuationClick = (suggestion: string) => {
    addMessage({ senderId: 'user', content: suggestion, type: 'text' });
    setShowContinuation(false);
  };

  const formatTime = (timestamp: number) => {
    const d = new Date(timestamp);
    return `${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}`;
  };

  // 空状态
  if (!currentMatch) {
    return (
      <div className="flex flex-col h-screen bg-deep-space font-body items-center justify-center px-6">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="text-center"
        >
          <div className="text-5xl mb-4">🎁</div>
          <p className="text-moon-white text-lg mb-2">请先揭晓本周盲盒</p>
          <p className="text-dim-star text-sm mb-6">匹配后即可开始聊天</p>
          <button
            onClick={() => navigate('/blindbox')}
            className="btn-primary px-6 py-2.5 text-sm"
          >
            去揭晓匹配
          </button>
        </motion.div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-screen bg-deep-space font-body">
      {/* 顶栏 */}
      <div className="flex items-center gap-3 px-4 py-3 glass shrink-0">
        <button
          onClick={() => navigate(-1)}
          className="p-1 rounded-full hover:bg-white/10 transition-colors"
        >
          <ArrowLeft className="w-5 h-5 text-moon-white" />
        </button>
        <span className="text-2xl">{currentMatch.avatar}</span>
        <div className="flex-1 min-w-0">
          <h1 className="text-base font-semibold text-moon-white font-display truncate">
            {currentMatch.nickname}
          </h1>
        </div>
        <span className="text-sm text-aurora-cyan font-medium">
          {currentMatch.compatibility}% 契合
        </span>
      </div>

      {/* AI 破冰话题建议条 */}
      {aiSuggestions.length > 0 && (
        <div className="shrink-0 px-4 py-2 overflow-x-auto flex gap-2 border-b border-white/5">
          {aiSuggestions.map((suggestion, index) => (
            <button
              key={index}
              onClick={() => sendAiSuggestion(index)}
              className="glass-light rounded-full px-3 py-1.5 text-xs text-moon-white/80 whitespace-nowrap hover:text-aurora-cyan transition-colors shrink-0"
            >
              💬 {suggestion}
            </button>
          ))}
        </div>
      )}

      {/* 消息列表 */}
      <div className="flex-1 overflow-y-auto px-4 py-4 space-y-3">
        {messages.map((msg, index) => {
          const isUser = msg.senderId === 'user';
          const isAi = msg.senderId === 'ai';

          return (
            <motion.div
              key={msg.id}
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.25 }}
            >
              {/* 用户消息 */}
              {isUser && (
                <div className="flex flex-col items-end">
                  <div className="max-w-[75%] bg-aurora-cyan/20 rounded-2xl rounded-br-md px-4 py-2.5 text-sm text-moon-white">
                    {msg.content}
                  </div>
                  <span className="mt-1 text-[10px] text-moon-white/30">
                    {formatTime(msg.timestamp)}
                  </span>
                </div>
              )}

              {/* AI 情绪安抚 */}
              {!isUser && msg.type === 'emotion-care' && (
                <div className="flex flex-col items-start">
                  <div className="max-w-[80%] bg-gradient-to-r from-soft-pink/20 to-star-gold/20 border border-soft-pink/30 rounded-2xl px-4 py-3">
                    <span className="text-sm mb-1 block">💫</span>
                    <p className="text-sm text-moon-white">{msg.content}</p>
                    <button
                      onClick={() => navigate('/support')}
                      className="mt-2 text-soft-pink text-xs hover:underline"
                    >
                      查看帮扶资源
                    </button>
                  </div>
                  <span className="mt-1 text-[10px] text-moon-white/30">
                    {formatTime(msg.timestamp)}
                  </span>
                </div>
              )}

              {/* AI 建议 */}
              {!isUser && !isAi && msg.type === 'ai-suggestion' && (
                <div className="flex flex-col items-start">
                  <div className="max-w-[80%] bg-star-gold/10 border border-star-gold/20 rounded-2xl px-4 py-2.5 text-sm text-moon-white">
                    {msg.content}
                  </div>
                  <span className="mt-1 text-[10px] text-moon-white/30">
                    {formatTime(msg.timestamp)}
                  </span>
                </div>
              )}

              {/* 对方消息（非 AI、非特殊类型） */}
              {!isUser && !isAi && msg.type === 'text' && (
                <div className="flex flex-col items-start">
                  <div className="max-w-[75%] bg-white/5 rounded-2xl rounded-bl-md px-4 py-2.5 text-sm text-moon-white">
                    {msg.content}
                  </div>
                  <span className="mt-1 text-[10px] text-moon-white/30">
                    {formatTime(msg.timestamp)}
                  </span>
                </div>
              )}

              {/* 活动卡片 */}
              {msg.type === 'activity-card' && (
                <div className="flex flex-col items-center">
                  <div className="w-[85%] glass rounded-2xl px-4 py-3 text-sm text-moon-white text-center">
                    🎯 {msg.content}
                  </div>
                  <span className="mt-1 text-[10px] text-moon-white/30">
                    {formatTime(msg.timestamp)}
                  </span>
                </div>
              )}
            </motion.div>
          );
        })}

        {/* 聊天热度检测 */}
        {messages.length >= 10 && (
          <motion.div
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            className="mx-auto"
          >
            <button
              onClick={() => navigate('/activity')}
              className="glass-light rounded-2xl px-4 py-3 text-sm text-moon-white hover:text-aurora-cyan transition-colors"
            >
              为你规划线下结伴 🎯
            </button>
          </motion.div>
        )}

        <div ref={messagesEndRef} />
      </div>

      {/* AI 续聊建议浮层 */}
      {showContinuation && (
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          exit={{ opacity: 0, y: 20 }}
          className="shrink-0 mx-4 mb-2 glass rounded-2xl p-4 relative"
        >
          <button
            onClick={() => setShowContinuation(false)}
            className="absolute top-3 right-3 text-moon-white/40 hover:text-moon-white transition-colors"
          >
            <X className="w-4 h-4" />
          </button>
          <div className="flex items-center gap-2 mb-3">
            <Sparkles className="w-4 h-4 text-star-gold" />
            <span className="text-xs text-star-gold font-medium">AI 续聊建议</span>
          </div>
          <div className="space-y-2">
            {continuationSuggestions.map((suggestion, index) => (
              <button
                key={index}
                onClick={() => handleContinuationClick(suggestion)}
                className="w-full text-left text-sm text-moon-white/80 hover:text-aurora-cyan bg-white/5 hover:bg-white/10 rounded-xl px-3 py-2 transition-colors"
              >
                {suggestion}
              </button>
            ))}
          </div>
        </motion.div>
      )}

      {/* 输入区 */}
      <div className="shrink-0 flex items-center gap-2 px-4 py-3 border-t border-white/5">
        <input
          ref={inputRef}
          type="text"
          value={inputText}
          onChange={(e) => setInputText(e.target.value)}
          onKeyDown={handleKeyDown}
          placeholder="输入消息..."
          className="flex-1 bg-deep-space/50 rounded-full px-4 py-2.5 text-sm text-moon-white placeholder-moon-white/30 outline-none focus:ring-1 focus:ring-aurora-cyan/30"
        />
        <button
          onClick={handleSend}
          className={`p-2.5 rounded-full transition-colors ${
            inputText.trim() ? 'text-aurora-cyan hover:bg-aurora-cyan/10' : 'text-moon-white/20'
          }`}
        >
          <Send className="w-5 h-5" />
        </button>
      </div>
    </div>
  );
}
