import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion } from 'framer-motion';
import { Sparkles } from 'lucide-react';
import { useAssessmentStore } from '@/stores/assessmentStore';
import { useUserStore } from '@/stores/userStore';
import { useMatchStore } from '@/stores/matchStore';
import { useCityStore } from '@/stores/cityStore';

const INTEREST_TAGS = [
  '探店', '运动', '看展', '音乐', '阅读', '咖啡',
  '徒步', '桌游', '摄影', '美食', '电影', '手工',
  '旅行', '烹饪', '绘画', '宠物', '园艺', '冥想',
];

// 雷达图参数：viewBox 200x200，中心(100,100)，半径70
const CX = 100;
const CY = 100;
const R = 70;

const AXES = [
  { key: 'openness', label: '开放性' },
  { key: 'conscientiousness', label: '尽责性' },
  { key: 'extraversion', label: '外向性' },
  { key: 'agreeableness', label: '宜人性' },
  { key: 'neuroticism', label: '神经质' },
] as const;

// 角度：0度(顶部)开放性O, 72度尽责性C, 144度外向性E, 216度宜人性A, 288度神经质N
function getAxisAngle(index: number): number {
  return (Math.PI * 2 * index) / 5 - Math.PI / 2;
}

function getAxisPoint(index: number, value: number) {
  const angle = getAxisAngle(index);
  const r = (value / 100) * R;
  return {
    x: CX + r * Math.cos(angle),
    y: CY + r * Math.sin(angle),
  };
}

function RadarChart({ values }: { values: number[] }) {
  // 3层网格线：半径 23/47/70
  const gridLevels = [23, 47, 70];

  return (
    <svg viewBox="0 0 200 200" className="w-64 h-64">
      <defs>
        <linearGradient id="radarGradient" x1="0%" y1="0%" x2="100%" y2="100%">
          <stop offset="0%" stopColor="#F5C842" stopOpacity="0.3" />
          <stop offset="100%" stopColor="#38F9D7" stopOpacity="0.3" />
        </linearGradient>
      </defs>

      {/* 背景网格线 3层 */}
      {gridLevels.map((level) => (
        <polygon
          key={level}
          points={AXES.map((_, i) => {
            const angle = getAxisAngle(i);
            const x = CX + level * Math.cos(angle);
            const y = CY + level * Math.sin(angle);
            return `${x},${y}`;
          }).join(' ')}
          fill="none"
          stroke="rgba(248, 246, 255, 0.1)"
          strokeWidth={1}
        />
      ))}

      {/* 轴线 */}
      {AXES.map((_, i) => {
        const angle = getAxisAngle(i);
        const ex = CX + R * Math.cos(angle);
        const ey = CY + R * Math.sin(angle);
        return (
          <line
            key={i}
            x1={CX}
            y1={CY}
            x2={ex}
            y2={ey}
            stroke="rgba(248, 246, 255, 0.1)"
            strokeWidth={1}
          />
        );
      })}

      {/* 数据区域多边形 */}
      <polygon
        points={values.map((v, i) => {
          const p = getAxisPoint(i, v);
          return `${p.x},${p.y}`;
        }).join(' ')}
        fill="url(#radarGradient)"
        stroke="rgba(245, 200, 66, 0.6)"
        strokeWidth={2}
      />

      {/* 数据点 */}
      {values.map((v, i) => {
        const p = getAxisPoint(i, v);
        return (
          <circle
            key={i}
            cx={p.x}
            cy={p.y}
            r={3.5}
            fill="#F5C842"
            stroke="#0F0A1E"
            strokeWidth={1.5}
          />
        );
      })}

      {/* 轴标签 */}
      {AXES.map((axis, i) => {
        const angle = getAxisAngle(i);
        const labelR = R + 16;
        const lx = CX + labelR * Math.cos(angle);
        const ly = CY + labelR * Math.sin(angle);
        return (
          <text
            key={i}
            x={lx}
            y={ly}
            textAnchor="middle"
            dominantBaseline="central"
            fill="rgba(248, 246, 255, 0.6)"
            fontSize={10}
            fontFamily="Noto Sans SC, sans-serif"
          >
            {axis.label}
          </text>
        );
      })}
    </svg>
  );
}

export default function AssessmentResult() {
  const navigate = useNavigate();
  const { result } = useAssessmentStore();
  const updateProfile = useUserStore((s) => s.updateProfile);
  const generateMatch = useMatchStore((s) => s.generateMatch);
  const currentCity = useCityStore((s) => s.currentCity);
  const user = useUserStore((s) => s.user);

  const [selectedTags, setSelectedTags] = useState<string[]>(
    user?.interestTags ?? []
  );

  if (!result) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[60vh]">
        <p className="text-moon-white/50 font-body text-lg">请先完成测评</p>
        <button
          onClick={() => navigate('/assessment')}
          className="btn-primary px-6 py-2.5 mt-6 text-sm font-body"
        >
          开始测评
        </button>
      </div>
    );
  }

  const toggleTag = (tag: string) => {
    setSelectedTags((prev) =>
      prev.includes(tag) ? prev.filter((t) => t !== tag) : [...prev, tag]
    );
  };

  const handleComplete = () => {
    if (selectedTags.length === 0) return;
    updateProfile({ interestTags: selectedTags });
    generateMatch(selectedTags, currentCity);
    navigate('/');
  };

  const values = [
    result.openness,
    result.conscientiousness,
    result.extraversion,
    result.agreeableness,
    result.neuroticism,
  ];

  return (
    <div className="flex flex-col items-center py-6 px-4">
      {/* 性格类型名称 */}
      <motion.h1
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        className="text-3xl font-display text-gradient-main mb-8"
      >
        {result.personalityType}
      </motion.h1>

      {/* 五维度雷达图 */}
      <motion.div
        initial={{ opacity: 0, scale: 0.8 }}
        animate={{ opacity: 1, scale: 1 }}
        transition={{ duration: 0.5, delay: 0.2 }}
        className="mb-8"
      >
        <RadarChart values={values} />
      </motion.div>

      {/* 性格描述 */}
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ delay: 0.4 }}
        className="glass-light rounded-2xl p-5 max-w-sm mb-6 text-center"
      >
        <p className="text-moon-white/80 font-body text-sm leading-relaxed">
          {result.description}
        </p>
      </motion.div>

      {/* AI 共情助手长期记忆提示 */}
      <motion.div
        initial={{ opacity: 0, y: 10 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ delay: 0.5 }}
        className="border border-star-gold/30 rounded-2xl px-5 py-4 mb-10 max-w-sm text-center"
      >
        <div className="flex items-center justify-center gap-2 mb-1.5">
          <Sparkles size={16} className="text-star-gold" />
          <span className="text-star-gold text-sm font-display">AI 共情助手</span>
        </div>
        <p className="text-moon-white/50 text-xs font-body leading-relaxed">
          你的性格画像将作为 AI 共情助手的长期记忆，为你提供个性化的聊天引导和情绪疏导
        </p>
      </motion.div>

      {/* 兴趣标签选择器 */}
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ delay: 0.6 }}
        className="w-full max-w-sm"
      >
        <h3 className="text-lg font-display text-moon-white mb-4 text-center">
          选择你的兴趣标签
        </h3>
        <div className="flex flex-wrap gap-2 justify-center mb-8">
          {INTEREST_TAGS.map((tag) => {
            const isSelected = selectedTags.includes(tag);
            return (
              <button
                key={tag}
                onClick={() => toggleTag(tag)}
                className={`px-3 py-1.5 rounded-full text-sm font-body border transition-all duration-200 ${
                  isSelected
                    ? 'bg-aurora-cyan/20 text-aurora-cyan border-aurora-cyan/30'
                    : 'bg-dark-matter/50 text-moon-white/50 border-transparent hover:border-moon-white/20'
                }`}
              >
                {tag}
              </button>
            );
          })}
        </div>

        {/* 完成按钮 */}
        <div className="text-center">
          <button
            onClick={handleComplete}
            disabled={selectedTags.length === 0}
            className={`btn-primary px-8 py-3 text-sm font-body transition-opacity ${
              selectedTags.length === 0 ? 'opacity-40 pointer-events-none' : ''
            }`}
          >
            完成，开启星遇之旅
          </button>
          {selectedTags.length === 0 && (
            <p className="text-moon-white/30 text-xs mt-2 font-body">
              请至少选择一个兴趣标签
            </p>
          )}
        </div>
      </motion.div>
    </div>
  );
}
