import { NavLink, Outlet } from 'react-router-dom';
import { Home, Gift, MessageCircle, Heart, User, MapPin } from 'lucide-react';
import { useCityStore } from '@/stores/cityStore';
import { useState } from 'react';
import StarField from './StarField';

const navItems = [
  { path: '/', icon: Home, label: '首页' },
  { path: '/blindbox', icon: Gift, label: '盲盒' },
  { path: '/chat', icon: MessageCircle, label: '聊天' },
  { path: '/support', icon: Heart, label: '帮扶' },
  { path: '/profile', icon: User, label: '我的' },
];

export default function Layout() {
  const { currentCity, cities, setCity } = useCityStore();
  const [showCityPicker, setShowCityPicker] = useState(false);

  return (
    <div className="min-h-screen relative font-body text-moon-white">
      <StarField />
      <div className="relative z-10 flex flex-col min-h-screen">
        {/* 顶部导航 */}
        <header className="glass sticky top-0 z-50 px-4 py-3 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <span className="text-xl">✨</span>
            <span className="font-display text-lg text-gradient-main">星遇盲盒</span>
          </div>
          <div className="relative">
            <button
              onClick={() => setShowCityPicker(!showCityPicker)}
              className="flex items-center gap-1 text-sm text-moon-white/70 hover:text-aurora-cyan transition-colors"
            >
              <MapPin size={14} />
              {currentCity}
            </button>
            {showCityPicker && (
              <div className="absolute right-0 top-full mt-2 glass rounded-xl p-3 max-h-60 overflow-y-auto w-40 z-50">
                <div className="grid grid-cols-2 gap-1">
                  {cities.map((city) => (
                    <button
                      key={city}
                      onClick={() => { setCity(city); setShowCityPicker(false); }}
                      className={`text-xs px-2 py-1.5 rounded-lg transition-all ${
                        city === currentCity
                          ? 'bg-aurora-cyan/20 text-aurora-cyan'
                          : 'text-moon-white/60 hover:text-moon-white hover:bg-white/5'
                      }`}
                    >
                      {city}
                    </button>
                  ))}
                </div>
              </div>
            )}
          </div>
        </header>

        {/* 主内容区 */}
        <main className="flex-1 overflow-y-auto">
          <div className="max-w-lg mx-auto px-4 py-6">
            <Outlet />
          </div>
        </main>

        {/* 底部导航 */}
        <nav className="glass sticky bottom-0 z-50 px-2 py-2">
          <div className="flex items-center justify-around">
            {navItems.map(({ path, icon: Icon, label }) => (
              <NavLink
                key={path}
                to={path}
                end={path === '/'}
                className={({ isActive }) =>
                  `flex flex-col items-center gap-0.5 px-3 py-1 rounded-xl transition-all ${
                    isActive
                      ? 'text-aurora-cyan'
                      : 'text-moon-white/40 hover:text-moon-white/70'
                  }`
                }
              >
                <Icon size={20} />
                <span className="text-[10px]">{label}</span>
              </NavLink>
            ))}
          </div>
        </nav>
      </div>
    </div>
  );
}
