import { create } from 'zustand';
import { persist } from 'zustand/middleware';

export interface MatchResult {
  id: string;
  nickname: string;
  avatar: string;
  compatibility: number;
  commonTags: string[];
  icebreakerTopics: string[];
  city: string;
}

interface MatchStore {
  currentMatch: MatchResult | null;
  matchRevealed: boolean;
  nextMatchTime: number;
  revealMatch: () => void;
  generateMatch: (userTags: string[], city: string) => void;
}

const mockMatches: Omit<MatchResult, 'commonTags' | 'icebreakerTopics'>[] = [
  { id: 'm1', nickname: '星河漫步者', avatar: '🌟', compatibility: 92, city: '北京' },
  { id: 'm2', nickname: '极光猎手', avatar: '🌌', compatibility: 87, city: '上海' },
  { id: 'm3', nickname: '月光收藏家', avatar: '🌙', compatibility: 85, city: '深圳' },
  { id: 'm4', nickname: '晨露旅人', avatar: '✨', compatibility: 89, city: '广州' },
  { id: 'm5', nickname: '云朵诗人', avatar: '☁️', compatibility: 83, city: '杭州' },
];

const allTags = ['探店', '运动', '看展', '音乐', '阅读', '咖啡', '徒步', '桌游', '摄影', '美食', '电影', '手工'];

const icebreakers = [
  '你们都热爱探索新事物，聊聊最近发现的一家宝藏小店吧',
  '你们的兴趣有交集，一起分享最近看的一部好电影如何',
  '你们都是行动派，这周末要不要一起去体验一下新活动',
];

function getNextSundayNoon(): number {
  const now = new Date();
  const dayOfWeek = now.getDay();
  const daysUntilSunday = dayOfWeek === 0 ? 0 : 7 - dayOfWeek;
  const nextSunday = new Date(now);
  nextSunday.setDate(now.getDate() + daysUntilSunday);
  nextSunday.setHours(12, 0, 0, 0);
  if (nextSunday.getTime() <= now.getTime()) {
    nextSunday.setDate(nextSunday.getDate() + 7);
  }
  return nextSunday.getTime();
}

export const useMatchStore = create<MatchStore>()(
  persist(
    (set, get) => ({
      currentMatch: null,
      matchRevealed: false,
      nextMatchTime: getNextSundayNoon(),
      revealMatch: () => set({ matchRevealed: true }),
      generateMatch: (userTags, city) => {
        const cityMatch = mockMatches.find((m) => m.city === city) || mockMatches[0];
        const commonTags = allTags.filter(() => Math.random() > 0.6).slice(0, 4);
        const match: MatchResult = {
          ...cityMatch,
          city,
          commonTags: commonTags.length > 0 ? commonTags : ['音乐', '美食'],
          icebreakerTopics: icebreakers,
        };
        const now = new Date();
        const shouldReveal = now.getDay() === 0 && now.getHours() >= 12;
        set({
          currentMatch: match,
          matchRevealed: shouldReveal,
          nextMatchTime: getNextSundayNoon(),
        });
      },
    }),
    { name: 'star-blindbox-match' }
  )
);
