import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion } from 'framer-motion';
import { ArrowLeft, MapPin, Clock, Wallet } from 'lucide-react';
import { useMatchStore } from '@/stores/matchStore';
import { useCityStore } from '@/stores/cityStore';
import { useChatStore } from '@/stores/chatStore';

interface ActivityPlan {
  type: string;
  emoji: string;
  locations: string[];
  budget: string;
}

const tagMapping: Record<string, ActivityPlan> = {
  '探店': { type: '探店打卡', emoji: '🍽️', locations: ['网红咖啡店', '隐藏日料', '甜品工坊'], budget: '50-150元' },
  '美食': { type: '探店打卡', emoji: '🍽️', locations: ['网红咖啡店', '隐藏日料', '甜品工坊'], budget: '50-150元' },
  '咖啡': { type: '探店打卡', emoji: '🍽️', locations: ['网红咖啡店', '隐藏日料', '甜品工坊'], budget: '50-150元' },
  '运动': { type: '户外运动', emoji: '🏃', locations: ['城市绿道', '攀岩馆', '羽毛球馆'], budget: '0-80元' },
  '徒步': { type: '户外运动', emoji: '🏃', locations: ['城市绿道', '攀岩馆', '羽毛球馆'], budget: '0-80元' },
  '看展': { type: '文艺看展', emoji: '🎨', locations: ['当代艺术馆', '摄影展', '独立画廊'], budget: '30-100元' },
  '摄影': { type: '文艺看展', emoji: '🎨', locations: ['当代艺术馆', '摄影展', '独立画廊'], budget: '30-100元' },
  '绘画': { type: '文艺看展', emoji: '🎨', locations: ['当代艺术馆', '摄影展', '独立画廊'], budget: '30-100元' },
  '音乐': { type: '影音休闲', emoji: '🎬', locations: ['Live House', '独立影院', '音乐节'], budget: '50-200元' },
  '电影': { type: '影音休闲', emoji: '🎬', locations: ['Live House', '独立影院', '音乐节'], budget: '50-200元' },
  '桌游': { type: '室内社交', emoji: '🎲', locations: ['桌游吧', '手工坊', '密室逃脱'], budget: '40-120元' },
  '手工': { type: '室内社交', emoji: '🎲', locations: ['桌游吧', '手工坊', '密室逃脱'], budget: '40-120元' },
};

const defaultPlan: ActivityPlan = {
  type: '休闲漫步',
  emoji: '🚶',
  locations: ['城市公园', '特色街区', '江边步道'],
  budget: '0-50元',
};

const timeSuggestions = ['本周末', '下周六下午'];

function generatePlans(commonTags: string[]): ActivityPlan[] {
  const seen = new Set<string>();
  const plans: ActivityPlan[] = [];

  for (const tag of commonTags) {
    const plan = tagMapping[tag];
    if (plan && !seen.has(plan.type)) {
      seen.add(plan.type);
      plans.push(plan);
    }
    if (plans.length >= 3) break;
  }

  if (plans.length === 0) {
    plans.push(defaultPlan);
  }

  return plans;
}

function pickLocations(locations: string[]): string[] {
  const count = Math.min(locations.length, 1 + Math.round(Math.random()));
  const shuffled = [...locations].sort(() => Math.random() - 0.5);
  return shuffled.slice(0, count);
}

function pickTime(): string {
  return timeSuggestions[Math.floor(Math.random() * timeSuggestions.length)];
}

export default function Activity() {
  const navigate = useNavigate();
  const { currentMatch } = useMatchStore();
  const { currentCity } = useCityStore();
  const { addMessage } = useChatStore();
  const [inviteSent, setInviteSent] = useState<string | null>(null);

  if (!currentMatch) {
    return (
      <div className="flex flex-col h-screen bg-deep-space font-body items-center justify-center px-6">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="text-center"
        >
          <div className="text-5xl mb-4">🎁</div>
          <p className="text-moon-white text-lg mb-2">请先揭晓本周盲盒匹配</p>
          <p className="text-dim-star text-sm mb-6">匹配后即可规划线下结伴方案</p>
          <button
            onClick={() => navigate('/blindbox')}
            className="btn-primary px-6 py-2.5 text-sm"
          >
            去揭晓匹配
          </button>
        </motion.div>
      </div>
    );
  }

  const plans = generatePlans(currentMatch.commonTags);

  const handleInvite = (plan: ActivityPlan, selectedLocations: string[], time: string) => {
    addMessage({
      senderId: 'user',
      content: `邀请你一起${plan.type}！地点：${selectedLocations.join('、')}，时间：${time}`,
      type: 'activity-card',
    });

    setInviteSent(plan.type);
    setTimeout(() => setInviteSent(null), 3000);
  };

  return (
    <div className="flex flex-col min-h-screen bg-deep-space font-body">
      {/* 顶栏 */}
      <div className="flex items-center gap-3 px-4 py-3 glass shrink-0">
        <button
          onClick={() => navigate(-1)}
          className="p-1 rounded-full hover:bg-white/10 transition-colors"
        >
          <ArrowLeft className="w-5 h-5 text-moon-white" />
        </button>
        <h1 className="text-base font-semibold text-moon-white font-display">线下结伴方案</h1>
      </div>

      {/* 匹配信息 */}
      <div className="px-4 py-3">
        <div className="flex items-center gap-2 text-sm text-dim-star">
          <span className="text-xl">{currentMatch.avatar}</span>
          <span>{currentMatch.nickname}</span>
          <span>·</span>
          <span>{currentCity}</span>
        </div>
        {currentMatch.commonTags.length > 0 && (
          <div className="flex flex-wrap gap-1.5 mt-2">
            {currentMatch.commonTags.map((tag) => (
              <span
                key={tag}
                className="px-2 py-0.5 rounded-full bg-star-purple/20 text-xs text-star-purple"
              >
                {tag}
              </span>
            ))}
          </div>
        )}
      </div>

      {/* 活动方案卡片 */}
      <div className="px-4 pb-6 space-y-4">
        {plans.map((plan, index) => {
          const selectedLocations = pickLocations(plan.locations);
          const time = timeSuggestions[index % timeSuggestions.length];
          const isSent = inviteSent === plan.type;

          return (
            <motion.div
              key={plan.type}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: index * 0.1, duration: 0.35 }}
              className="glass rounded-2xl p-5"
            >
              {/* 类型头部 */}
              <div className="flex items-center gap-3 mb-4">
                <span className="text-4xl">{plan.emoji}</span>
                <div>
                  <h3 className="text-lg font-semibold text-moon-white font-display">{plan.type}</h3>
                  <p className="text-xs text-dim-star">基于你们的共同兴趣</p>
                </div>
              </div>

              {/* 推荐地点 */}
              <div className="space-y-2 mb-4">
                <div className="flex items-center gap-2 text-sm text-moon-white">
                  <MapPin className="w-4 h-4 text-aurora-cyan" />
                  <span>{selectedLocations.join('、')}</span>
                </div>
                <div className="flex items-center gap-2 text-sm text-moon-white">
                  <Clock className="w-4 h-4 text-star-gold" />
                  <span>{time}</span>
                </div>
                <div className="flex items-center gap-2 text-sm text-moon-white">
                  <Wallet className="w-4 h-4 text-soft-pink" />
                  <span>{plan.budget}</span>
                </div>
              </div>

              {/* 邀请按钮 */}
              <button
                onClick={() => handleInvite(plan, selectedLocations, time)}
                disabled={isSent}
                className={`w-full btn-primary py-2.5 text-sm ${
                  isSent ? 'opacity-70 cursor-not-allowed' : ''
                }`}
              >
                {isSent ? '邀请已发送 ✨' : '邀请 TA'}
              </button>
            </motion.div>
          );
        })}
      </div>
    </div>
  );
}
