import { create } from 'zustand';
import { persist } from 'zustand/middleware';

interface CityStore {
  currentCity: string;
  cities: string[];
  setCity: (city: string) => void;
}

export const useCityStore = create<CityStore>()(
  persist(
    (set) => ({
      currentCity: '北京',
      cities: [
        '北京', '上海', '广州', '深圳', '杭州',
        '成都', '重庆', '武汉', '南京', '西安',
        '长沙', '苏州', '天津', '青岛', '大连',
        '厦门', '昆明', '郑州', '合肥', '福州',
      ],
      setCity: (city) => set({ currentCity: city }),
    }),
    { name: 'star-blindbox-city' }
  )
);
