import { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { motion } from 'framer-motion';
import { Mail, Lock, Eye, EyeOff } from 'lucide-react';
import { useUserStore } from '@/stores/userStore';
import StarField from '@/components/StarField';

export default function Login() {
  const navigate = useNavigate();
  const login = useUserStore((s) => s.login);

  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [errors, setErrors] = useState<{ email?: string; password?: string; general?: string }>({});

  const validate = (): boolean => {
    const newErrors: typeof errors = {};
    if (!email) {
      newErrors.email = '请输入邮箱';
    } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      newErrors.email = '邮箱格式不正确';
    }
    if (!password) {
      newErrors.password = '请输入密码';
    }
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!validate()) return;

    const success = login({ email, password });
    if (success) {
      navigate('/');
    } else {
      setErrors({ general: '邮箱或密码错误' });
    }
  };

  return (
    <div className="min-h-screen relative font-body text-moon-white flex items-center justify-center">
      <StarField />
      <motion.div
        initial={{ opacity: 0, y: 30 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.5 }}
        className="relative z-10 w-full max-w-sm mx-4"
      >
        <div className="glass rounded-3xl p-8 space-y-6">
          <h1 className="font-display text-3xl text-center text-gradient-main">
            欢迎回来
          </h1>

          {errors.general && (
            <p className="text-soft-pink text-sm text-center">{errors.general}</p>
          )}

          <form onSubmit={handleSubmit} className="space-y-4">
            {/* 邮箱 */}
            <div className="space-y-1.5">
              <div className="relative">
                <Mail size={18} className="absolute left-3 top-1/2 -translate-y-1/2 text-moon-white/40" />
                <input
                  type="email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  placeholder="邮箱"
                  className="w-full bg-deep-space/50 border border-moon-white/10 rounded-xl pl-10 pr-4 py-3 text-sm
                    placeholder:text-moon-white/30 focus:outline-none focus:border-aurora-cyan/50 transition-colors"
                />
              </div>
              {errors.email && <p className="text-soft-pink text-xs pl-1">{errors.email}</p>}
            </div>

            {/* 密码 */}
            <div className="space-y-1.5">
              <div className="relative">
                <Lock size={18} className="absolute left-3 top-1/2 -translate-y-1/2 text-moon-white/40" />
                <input
                  type={showPassword ? 'text' : 'password'}
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  placeholder="密码"
                  className="w-full bg-deep-space/50 border border-moon-white/10 rounded-xl pl-10 pr-10 py-3 text-sm
                    placeholder:text-moon-white/30 focus:outline-none focus:border-aurora-cyan/50 transition-colors"
                />
                <button
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-moon-white/40 hover:text-moon-white/70 transition-colors"
                >
                  {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                </button>
              </div>
              {errors.password && <p className="text-soft-pink text-xs pl-1">{errors.password}</p>}
            </div>

            <button type="submit" className="btn-primary w-full py-3 text-base mt-2">
              登录
            </button>
          </form>

          <p className="text-center text-sm text-moon-white/50">
            还没有账号？
            <Link to="/register" className="text-aurora-cyan hover:underline ml-1">
              去注册
            </Link>
          </p>
        </div>
      </motion.div>
    </div>
  );
}
