import { create } from 'zustand';
import { persist } from 'zustand/middleware';

export interface AssessmentResult {
  openness: number;
  conscientiousness: number;
  extraversion: number;
  agreeableness: number;
  neuroticism: number;
  description: string;
  personalityType: string;
}

interface AssessmentStore {
  answers: number[];
  result: AssessmentResult | null;
  setAnswer: (index: number, value: number) => void;
  calculateResult: () => AssessmentResult;
  reset: () => void;
}

const personalityDescriptions: Record<string, { description: string; type: string }> = {
  'O-high_C-high_E-high_A-high_N-low': { description: '你是一位充满创造力且自律的社交达人，温暖可靠，情绪稳定，是天生的团队灵魂人物。', type: '星辰领航者' },
  'O-high_C-high_E-low_A-high_N-low': { description: '你内心世界丰富而有条理，温和体贴且情绪稳定，是值得深交的灵魂伴侣。', type: '静水流深者' },
  'O-high_C-low_E-high_A-high_N-high': { description: '你热情奔放、充满好奇，感性而真诚，需要被理解和接纳你的丰富情绪。', type: '流星追梦人' },
  'O-low_C-high_E-low_A-high_N-low': { description: '你务实稳健、温和可靠，虽不张扬但内心笃定，是默默守护的力量。', type: '北斗守望者' },
  'default': { description: '你拥有独特的性格组合，既有探索未知的勇气，也有安于内心的从容，是一个迷人而复杂的存在。', type: '星云漫游者' },
};

function getPersonalityKey(r: AssessmentResult): string {
  const h = (v: number) => v > 60 ? 'high' : 'low';
  return `O-${h(r.openness)}_C-${h(r.conscientiousness)}_E-${h(r.extraversion)}_A-${h(r.agreeableness)}_N-${h(r.neuroticism)}`;
}

export const useAssessmentStore = create<AssessmentStore>()(
  persist(
    (set, get) => ({
      answers: [],
      result: null,
      setAnswer: (index, value) => {
        const answers = [...get().answers];
        answers[index] = value;
        set({ answers });
      },
      calculateResult: () => {
        const { answers } = get();
        const chunkSize = Math.ceil(answers.length / 5);
        const dims = [0, 1, 2, 3, 4].map((i) => {
          const slice = answers.slice(i * chunkSize, (i + 1) * chunkSize);
          if (slice.length === 0) return 50;
          return Math.round((slice.reduce((a, b) => a + b, 0) / slice.length) * 10);
        });
        const result: AssessmentResult = {
          openness: dims[0],
          conscientiousness: dims[1],
          extraversion: dims[2],
          agreeableness: dims[3],
          neuroticism: dims[4],
          description: '',
          personalityType: '',
        };
        const key = getPersonalityKey(result);
        const p = personalityDescriptions[key] || personalityDescriptions['default'];
        result.description = p.description;
        result.personalityType = p.type;
        set({ result });
        return result;
      },
      reset: () => set({ answers: [], result: null }),
    }),
    { name: 'star-blindbox-assessment' }
  )
);
